{
  "steps": [
    {
      "action": "Provide a notice to the data principal at the time of or before requesting personal data, specifying the personal data sought to be collected and the purpose of processing.",
      "provision_id": "dpdp_act_2023_sec_5"
    },
    {
      "action": "Ensure the notice is provided in clear and plain language, and if requested by the data principal, provide it in any of the languages specified in the Eighth Schedule to the Constitution.",
      "provision_id": "dpdp_act_2023_sec_5"
    },
    {
      "action": "Include in the notice the manner in which the data principal may exercise their rights and the procedure for making a grievance complaint to the Data Protection Board of India.",
      "provision_id": "dpdp_act_2023_sec_5"
    }
  ]
}

{
  "steps": [
    {
      "action": "The Data Fiduciary must give the Data Protection Board of India and each affected Data Principal intimation of a personal data breach in such form and manner as may be prescribed.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "The specific timelines for reporting a personal data breach to the Board and affected users are to be defined under the rules framed by the Central Government.",
      "provision_id": "dpdp_act_2023_sec_40"
    }
  ]
}

{
  "steps": [
    {
      "action": "Obtain verifiable consent from the parent or lawful guardian before processing any personal data of a child (a person under 18 years of age).",
      "provision_id": "dpdp_act_2023_sec_9"
    },
    {
      "action": "Ensure that the manner of obtaining verifiable parental consent is in accordance with the rules prescribed by the Central Government.",
      "provision_id": "dpdp_act_2023_sec_9"
    },
    {
      "action": "Refrain from any tracking or behavioral monitoring of children or targeted advertising directed at children.",
      "provision_id": "dpdp_act_2023_sec_9"
    }
  ]
}

{
  "steps": [
    {
      "action": "Register with the Data Protection Board of India to operate as a Consent Manager, ensuring the entity is a body corporate.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "Establish a transparent mechanism for data principals to provide, manage, review, and withdraw consent through an accessible platform.",
      "provision_id": "dpdp_act_2023_sec_6"
    },
    {
      "action": "Maintain a comprehensive record of consent provided by data principals and ensure the integrity of the consent management process.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "Act exclusively on behalf of the data principal and ensure that the consent request is clear, specific, and informed.",
      "provision_id": "dpdp_act_2023_sec_6"
    },
    {
      "action": "Implement robust technical and organizational measures to ensure the security and confidentiality of the consent data processed.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "Comply with the specific operational, technical, and financial standards as prescribed by the Central Government under the rules.",
      "provision_id": "dpdp_act_2023_sec_40"
    }
  ]
}

{
  "steps": [
    {
      "action": "Implement reasonable security safeguards to prevent personal data breach, including technical and organizational measures.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "Maintain a comprehensive information security policy and implement physical, technical, and administrative security measures.",
      "provision_id": "dpdp_rules_2025_rule_3"
    },
    {
      "action": "Ensure regular security audits and vulnerability assessments of the data processing systems.",
      "provision_id": "dpdp_rules_2025_rule_4"
    },
    {
      "action": "Appoint a Data Protection Officer and establish a grievance redressal mechanism to handle security-related concerns.",
      "provision_id": "dpdp_act_2023_sec_8"
    },
    {
      "action": "Implement encryption, pseudonymization, and access control mechanisms to protect personal data during processing.",
      "provision_id": "dpdp_rules_2025_rule_5"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure that the transfer of personal data outside India is not restricted by the Central Government through a notification specifying countries or territories to which such transfer is prohibited.",
      "provision_id": "dpdp_act_2023_sec_16"
    },
    {
      "action": "Comply with any sectoral regulations (such as those issued by the RBI) that mandate the storage of specific data (e.g., payment system data) exclusively within India, which may effectively restrict cross-border transfer.",
      "provision_id": "rbi_payment_data_storage_2018_dir_1"
    },
    {
      "action": "Ensure that the transfer does not contravene any other applicable laws or specific directions issued by the Central Government regarding data sovereignty or national security.",
      "provision_id": "dpdp_act_2023_sec_16"
    }
  ]
}

{
  "steps": [
    {
      "action": "Mandatory reporting of cyber security incidents to CERT-In within 6 hours of noticing such incidents or being brought to notice about such incidents.",
      "provision_id": "cert_in_directions_2022_dir_1"
    }
  ]
}

{
  "steps": [
    {
      "action": "Maintain ICT system logs for a period of 180 days and ensure they are securely stored within the Indian jurisdiction.",
      "provision_id": "cert_in_directions_2022_dir_4"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify password as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_i"
    },
    {
      "action": "Identify financial information such as bank account, credit card, debit card, or other payment instrument details as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_ii"
    },
    {
      "action": "Identify physical, physiological, and mental health condition as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_iii"
    },
    {
      "action": "Identify sexual orientation as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_iv"
    },
    {
      "action": "Identify medical records and history as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_v"
    },
    {
      "action": "Identify biometric information as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_vi"
    },
    {
      "action": "Identify any detail relating to the above clauses provided to a body corporate for providing service as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_vii"
    },
    {
      "action": "Identify information received under the above clauses by a body corporate for processing, stored or processed under lawful contract or otherwise as sensitive personal data or information.",
      "provision_id": "spdi_rules_2011_rule_3_viii"
    }
  ]
}

{
  "steps": [
    {
      "action": "Implement and maintain reasonable security practices and procedures to protect sensitive personal data or information.",
      "provision_id": "it_act_2000_sec_43A"
    },
    {
      "action": "Compensate the affected person for any wrongful loss or gain resulting from the failure to implement and maintain such reasonable security practices.",
      "provision_id": "it_act_2000_sec_43A"
    },
    {
      "action": "Adhere to the prescribed rules for the collection and disclosure of sensitive personal data to avoid liability for negligence in implementing security standards.",
      "provision_id": "spdi_rules_2011_rule_8"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure a minimum of two partners are present to incorporate a Limited Liability Partnership.",
      "provision_id": "llp_act_2008_sec_5"
    },
    {
      "action": "Appoint at least two designated partners, who are individuals, at least one of whom must be a resident in India.",
      "provision_id": "llp_act_2008_sec_7"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the company has no security interest in its assets and all shareholders have consented to the conversion.",
      "provision_id": "llp_act_2008_sec_58"
    },
    {
      "action": "File an application for conversion with the Registrar of Companies (ROC) in the prescribed form along with the statement of shareholders.",
      "provision_id": "llp_act_2008_sch_3"
    },
    {
      "action": "Obtain the Certificate of Registration of conversion from the Registrar.",
      "provision_id": "llp_act_2008_sec_58"
    },
    {
      "action": "Notify the Registrar of Companies about the conversion within 15 days of the registration of the LLP.",
      "provision_id": "llp_act_2008_sec_58"
    },
    {
      "action": "Ensure all pending filings under the Companies Act are completed prior to the conversion process.",
      "provision_id": "ca_2013_sec_403"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the non-compete clause is limited to the duration of the contract, as restraint of trade during the subsistence of a contract is generally considered valid and not in violation of the law.",
      "provision_id": "contract_act_1872_sec_27"
    },
    {
      "action": "Avoid drafting non-compete clauses that extend beyond the termination of the contract, as post-termination restraints are generally held to be void as they constitute a restraint of trade.",
      "provision_id": "contract_act_1872_sec_27"
    },
    {
      "action": "Ensure that if the non-compete is part of the sale of goodwill, it is reasonable in terms of local limits and duration to qualify for the statutory exception.",
      "provision_id": "contract_act_1872_sec_27"
    }
  ]
}

{
  "steps": [
    {
      "action": "Determine if the contract contains a valid liquidated damages clause, which serves as a pre-estimate of damages agreed upon by the parties to be paid in the event of a breach.",
      "provision_id": "contract_act_1872_sec_74"
    },
    {
      "action": "Assess whether the amount named in the contract is a genuine pre-estimate of loss or a penalty; if it is a penalty, the court will award only reasonable compensation not exceeding the amount so named.",
      "provision_id": "contract_act_1872_sec_74"
    },
    {
      "action": "Establish the actual loss or damage suffered by the aggrieved party, as the court requires proof of loss to award compensation, even where a liquidated damages clause exists.",
      "provision_id": "contract_act_1872_sec_73"
    },
    {
      "action": "Ensure that the compensation claimed does not include remote or indirect loss or damage sustained by reason of the breach, unless such loss was in the contemplation of the parties at the time of the contract.",
      "provision_id": "contract_act_1872_sec_73"
    }
  ]
}

{
  "steps": [
    {
      "action": "Define a contract of indemnity as a contract by which one party promises to save the other from loss caused to him by the conduct of the promisor himself, or by the conduct of any other person.",
      "provision_id": "contract_act_1872_sec_124"
    },
    {
      "action": "Establish the right of the indemnity-holder to recover all damages which he may be compelled to pay in any suit in respect of any matter to which the promise to indemnify applies.",
      "provision_id": "contract_act_1872_sec_125"
    },
    {
      "action": "Establish the right of the indemnity-holder to recover all costs which he may be compelled to pay in any such suit, provided he did not contravene the orders of the promisor and acted as a prudent man would have acted in his own case.",
      "provision_id": "contract_act_1872_sec_125"
    },
    {
      "action": "Establish the right of the indemnity-holder to recover all sums which he may have paid under the terms of any compromise of any such suit, provided the compromise was not contrary to the orders of the promisor and was one which a prudent man would have made.",
      "provision_id": "contract_act_1872_sec_125"
    }
  ]
}

{
  "steps": [
    {
      "action": "A company must spend on Corporate Social Responsibility (CSR) if it meets any of the following criteria during the immediately preceding financial year: (i) net worth of rupees five hundred crore or more, (ii) turnover of rupees one thousand crore or more, or (iii) a net profit of rupees five crore or more.",
      "provision_id": "ca_2013_sec_135"
    },
    {
      "action": "The Board of every company covered under the CSR mandate must ensure that the company spends, in every financial year, at least two percent of the average net profits of the company made during the three immediately preceding financial years.",
      "provision_id": "ca_2013_sec_135"
    }
  ]
}

{
  "steps": [
    {
      "action": "The Board of Directors must recommend an individual or firm as the auditor to the shareholders for appointment at the first Annual General Meeting (AGM).",
      "provision_id": "ca_2013_sec_139"
    },
    {
      "action": "The company must obtain a written consent from the proposed auditor and a certificate confirming that the appointment, if made, will be in accordance with the conditions prescribed.",
      "provision_id": "ca_2013_sec_139"
    },
    {
      "action": "The company must pass an ordinary resolution at the AGM to appoint the auditor, who shall hold office from the conclusion of that meeting until the conclusion of the sixth AGM.",
      "provision_id": "ca_2013_sec_139"
    },
    {
      "action": "The company must file a notice of the appointment of the auditor with the Registrar of Companies in Form ADT-1 within 15 days of the meeting in which the auditor is appointed.",
      "provision_id": "ca_2013_sec_139"
    }
  ]
}

{
  "steps": [
    {
      "action": "Board of Directors must approve the rights issue proposal and determine the issue price, record date, and terms of the offer at a duly convened board meeting.",
      "provision_id": "ca_2013_sec_179"
    },
    {
      "action": "Send the offer letter to existing shareholders via registered post, speed post, or electronic mode, specifying the number of shares offered and the time period for acceptance (not less than 15 days and not more than 30 days).",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "File the offer letter with the Registrar of Companies (ROC) in Form MGT-14 if required by the articles or specific board resolutions.",
      "provision_id": "ca_2013_sec_117"
    },
    {
      "action": "Receive acceptance or renunciation from shareholders within the specified offer period.",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "Convene a subsequent board meeting to allot the shares to the shareholders who have accepted the offer.",
      "provision_id": "ca_2013_sec_62"
    },
    {
      "action": "File the return of allotment in Form PAS-3 with the Registrar of Companies within 30 days of the allotment.",
      "provision_id": "ca_2013_sec_39"
    },
    {
      "action": "Issue share certificates to the allottees within two months from the date of allotment.",
      "provision_id": "ca_2013_sec_56"
    },
    {
      "action": "Pay the requisite stamp duty on the issuance of share certificates as per the state-specific stamp act.",
      "provision_id": "indian_stamp_act_1899_sec_3"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify persons ineligible to submit a resolution plan, including undischarged insolvents, willful defaulters, persons whose accounts are classified as non-performing assets for a specified period, and persons convicted of certain offenses.",
      "provision_id": "ibc_2016_sec_29A"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the e-commerce entity does not engage in unfair trade practices such as false representation of goods, misleading advertisements, or withholding information, which are prohibited under the Consumer Protection Act.",
      "provision_id": "consumer_protection_act_2019_sec_2"
    },
    {
      "action": "Adhere to the specific duties of e-commerce entities, including the requirement to provide clear information on returns, refunds, exchange, warranty, and delivery, and to ensure transparency in pricing.",
      "provision_id": "consumer_protection_act_2019_sec_94"
    },
    {
      "action": "Comply with the Consumer Protection (E-Commerce) Rules, 2020, which mandate the display of seller details, grievance redressal mechanisms, and prohibition of manipulation of search results to favor specific sellers.",
      "provision_id": "consumer_protection_act_2019_rule_4"
    },
    {
      "action": "Establish a robust grievance redressal mechanism and appoint a grievance officer to address consumer complaints within the prescribed timelines.",
      "provision_id": "consumer_protection_act_2019_rule_5"
    },
    {
      "action": "Ensure that the marketplace does not adopt unfair contract terms that cause significant imbalance in the rights and obligations of the consumer.",
      "provision_id": "consumer_protection_act_2019_sec_2"
    }
  ]
}

{
  "steps": [
    {
      "action": "Identify subject matter that is not considered an invention, including frivolous inventions, inventions contrary to natural laws, or those causing public disorder or morality issues.",
      "provision_id": "patents_act_1970_sec_3_a_b_c"
    },
    {
      "action": "Exclude discovery of scientific principles, formulation of abstract theories, or discovery of any living thing or non-living substance occurring in nature from patentability.",
      "provision_id": "patents_act_1970_sec_3_c_d"
    },
    {
      "action": "Exclude mere schemes, rules, or methods of performing mental acts or methods of playing games from patentability.",
      "provision_id": "patents_act_1970_sec_3_m"
    },
    {
      "action": "Exclude computer programmes per se or algorithms from patentability, unless they are claimed in conjunction with a novel hardware component or provide a technical contribution.",
      "provision_id": "patents_act_1970_sec_3_k"
    }
  ]
}

{
  "steps": [
    {
      "action": "The term of a patent in India is 20 years from the date of filing the application for the patent.",
      "provision_id": "patents_act_1970_sec_53"
    }
  ]
}

{
  "steps": [
    {
      "action": "The true and first inventor or their assignee is entitled to apply for a patent.",
      "provision_id": "patents_act_1970_sec_6"
    },
    {
      "action": "If an invention is made by an employee during the course of employment, the employer may be entitled to the patent if there is an express or implied contract of service assigning the rights to the employer.",
      "provision_id": "patents_act_1970_sec_7"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the patent assignment agreement is in writing and reduced to the form of a document embodying all the terms and conditions governing their rights and obligations.",
      "provision_id": "patents_act_1970_sec_68"
    },
    {
      "action": "Submit the assignment document to the Controller of Patents for registration to ensure the title transfer is legally recognized and enforceable.",
      "provision_id": "patents_act_1970_sec_68"
    }
  ]
}

{
  "steps": [
    {
      "action": "Refusal on absolute grounds, including marks lacking distinctive character, marks consisting exclusively of signs or indications which may serve in trade to designate the kind, quality, quantity, intended purpose, values, geographical origin, or the time of production of goods or rendering of service, or marks that are customary in the current language or established practices of the trade.",
      "provision_id": "trademarks_act_1999_sec_9"
    },
    {
      "action": "Refusal on relative grounds, including identity or similarity to an earlier trademark for identical or similar goods or services, which is likely to cause confusion on the part of the public or association with the earlier trademark.",
      "provision_id": "trademarks_act_1999_sec_11"
    },
    {
      "action": "Refusal if the mark is likely to deceive the public or cause confusion, or if it contains matter likely to hurt the religious susceptibilities of any class or section of the citizens of India.",
      "provision_id": "trademarks_act_1999_sec_9"
    },
    {
      "action": "Refusal if the mark comprises or contains scandalous or obscene matter, or if its use is prohibited under the Emblems and Names (Prevention of Improper Use) Act, 1950.",
      "provision_id": "trademarks_act_1999_sec_9"
    }
  ]
}

{
  "steps": [
    {
      "action": "A trademark registration is valid for a period of 10 years from the date of application.",
      "provision_id": "trademarks_act_1999_sec_25"
    },
    {
      "action": "The registration may be renewed for successive periods of 10 years by filing an application in the prescribed manner and paying the requisite renewal fee.",
      "provision_id": "trademarks_act_1999_sec_25"
    },
    {
      "action": "An application for renewal must be made within the prescribed time frame, typically not more than six months before the expiration of the last registration.",
      "provision_id": "trademarks_act_1999_sec_25"
    }
  ]
}

{
  "steps": [
    {
      "action": "Infringement occurs when a person, not being the registered proprietor or a permitted user, uses in the course of trade a mark which is identical with or deceptively similar to the registered trademark in relation to goods or services for which the trademark is registered.",
      "provision_id": "trademarks_act_1999_sec_29"
    },
    {
      "action": "Infringement also occurs when a person uses a mark identical or similar to a well-known registered trademark, which takes unfair advantage of or is detrimental to the distinctive character or repute of the registered trademark.",
      "provision_id": "trademarks_act_1999_sec_29"
    },
    {
      "action": "The registered proprietor may seek relief in a suit for infringement, which includes permanent or temporary injunctions, and at the option of the plaintiff, either damages or an account of profits.",
      "provision_id": "trademarks_act_1999_sec_135"
    },
    {
      "action": "The court may also order the destruction or erasure of the infringing labels, marks, or packaging, and may appoint a local commissioner to seize infringing goods.",
      "provision_id": "trademarks_act_1999_sec_135"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the trademark is validly registered under the Trademarks Act, 1999, as licensing is only permitted for registered trademarks.",
      "provision_id": "trademarks_act_1999_sec_18"
    },
    {
      "action": "Draft a written license agreement clearly defining the terms of use, quality control, and the nature of the permitted use by the franchisee.",
      "provision_id": "trademarks_act_1999_sec_48"
    },
    {
      "action": "Apply to the Registrar of Trademarks to register the franchisee as a 'registered user' by submitting the agreement and a supporting affidavit.",
      "provision_id": "trademarks_act_1999_sec_49"
    },
    {
      "action": "Ensure the agreement includes provisions for the proprietor to exercise quality control over the goods or services to prevent the trademark from becoming deceptive or losing distinctiveness.",
      "provision_id": "trademarks_act_1999_sec_50"
    }
  ]
}

{
  "steps": [
    {
      "action": "Piracy of a registered design is defined as the application of a design or any fraudulent or obvious imitation thereof to any article in any class of goods in which the design is registered, without the consent of the registered proprietor.",
      "provision_id": "designs_act_2000_sec_22"
    },
    {
      "action": "It also includes the import for the purposes of sale of any article to which the design or imitation has been applied, or the publication or exposure for sale of such an article knowing that the design has been applied without the consent of the registered proprietor.",
      "provision_id": "designs_act_2000_sec_22"
    }
  ]
}

{
  "steps": [
    {
      "action": "Ensure the electronic contract is formed through a valid offer and acceptance process, which is legally recognized for electronic records.",
      "provision_id": "it_act_2000_sec_10A"
    },
    {
      "action": "Verify that the electronic signature or click-wrap acceptance method satisfies the requirement for authentication of electronic records.",
      "provision_id": "it_act_2000_sec_3"
    },
    {
      "action": "Ensure the contract meets the essential elements of a valid contract, including free consent and lawful consideration, as electronic form does not invalidate the agreement.",
      "provision_id": "contract_act_1872_sec_10"
    },
    {
      "action": "Maintain the integrity and admissibility of the electronic contract as evidence in legal proceedings by ensuring it is stored in a manner that preserves its original form.",
      "provision_id": "it_act_2000_sec_65B"
    }
  ]
}

{
  "steps": [
    {
      "action": "Determine the aggregate turnover threshold for registration, which is generally 20 lakhs for services and 40 lakhs for the supply of goods (subject to specific state-wise variations).",
      "provision_id": "cgst_act_2017_sec_22"
    },
    {
      "action": "Ensure compulsory registration regardless of turnover if engaged in inter-state taxable supply or other specified categories.",
      "provision_id": "cgst_act_2017_sec_24"
    }
  ]
}

{
  "steps": [
    {
      "action": "Possess a valid tax invoice or debit note issued by a registered supplier.",
      "provision_id": "cgst_act_2017_sec_16_2_a"
    },
    {
      "action": "Ensure the details of the invoice or debit note have been furnished by the supplier in the statement of outward supplies and such details have been communicated to the recipient.",
      "provision_id": "cgst_act_2017_sec_16_2_aa"
    },
    {
      "action": "Actually receive the goods or services or both.",
      "provision_id": "cgst_act_2017_sec_16_2_b"
    },
    {
      "action": "Ensure the tax charged in respect of such supply has been actually paid to the Government.",
      "provision_id": "cgst_act_2017_sec_16_2_c"
    },
    {
      "action": "Furnish the return under section 39 of the CGST Act.",
      "provision_id": "cgst_act_2017_sec_16_2_d"
    },
    {
      "action": "Pay the value of the supply along with the tax payable thereon to the supplier within 180 days from the date of issue of invoice, failing which the credit must be added to the output tax liability.",
      "provision_id": "cgst_act_2017_sec_16_2_second_proviso"
    }
  ]
}

{
  "steps": [
    {
      "action": "Verify if the startup's aggregate turnover in the preceding financial year did not exceed the prescribed threshold (currently ₹1.5 crore, or ₹75 lakhs for special category states).",
      "provision_id": "cgst_act_2017_sec_10"
    },
    {
      "action": "Ensure the startup is not engaged in the supply of services other than those specifically permitted under the scheme (e.g., restaurant services) or inter-state outward supplies of goods.",
      "provision_id": "cgst_act_2017_sec_10"
    },
    {
      "action": "Ensure the startup is not engaged in the supply of non-taxable goods or goods through an electronic commerce operator who is required to collect tax at source.",
      "provision_id": "cgst_act_2017_sec_10"
    },
    {
      "action": "File an intimation for opting into the composition levy in the prescribed form on the GST portal.",
      "provision_id": "cgst_rules_2017_rule_3"
    }
  ]
}

